function recalculateFormulas() {
    let formulasFound = false;
    const keys = Object.keys(estado);

    for (const key of keys) {
        let value = estado[key];

        // 1. Verificar si el valor almacenado es una fórmula calculada o si comienza con '=' (si fue ingresado como texto).
        // Usamos la lógica de formato que implementaremos para saber qué recalcular.
        const formulaMatch = value ? value.match(/^__FORMULA_START__:(.+?)\|(.+)$/) : null;

        if (formulaMatch) {
            formulasFound = true;
            const originalFormulaString = formulaMatch[1];
            // Intentamos reevaluar la fórmula con el estado actual
            const result = evaluateFormula(originalFormulaString);

            if (result !== null) {
                // Actualizamos el estado con el nuevo resultado calculado. Mantenemos el formato de fórmula para preservar el contexto.
                estado[key] = `__FORMULA_START__:${originalFormulaString}|${result}`;
            } else {
                 // Si falla la reevaluación, dejamos el valor tal como está (el último resultado conocido).
            }
        } 
        // Nota: Si no tiene el marcador de fórmula, asumimos que es un dato fijo o una fórmula ingresada manualmente y su estado ya fue procesado en handleCellInteraction.
    }

    if (formulasFound) {
        console.log("Recálculo de fórmulas completado.");
    }
}
