function evaluateFormula(formulaString) {
    let formula = formulaString.trim();

    // 1. Manejo de rangos simples (SUMA(A1:A3))
    const sumMatch = formula.match(/SUMA\s*\(([^)]+)\)/i);
    if (sumMatch && sumMatch[1]) {
        const rangeString = sumMatch[1];
        const keys = getKeysInRange(rangeString);
        let sum = 0;
        for (const key of keys) {
            // Aseguramos que siempre tomamos el valor actual del estado, incluso si es un resultado calculado.
            const value = estado[key] || '0';
            // Intentamos convertir a número para sumar. Si falla, se trata como cero.
            const numValue = parseFloat(value);
            if (!isNaN(numValue)) {
                sum += numValue;
            }
        }
        return sum.toString();
    }

    // 2. Manejo de operaciones binarias o múltiples (A1-B1, A1+B1*C1)
    try {
        let expression = formula;

        // Reemplazamos referencias tipo 'A1' por sus valores numéricos para JS eval()
        // Este regex captura cualquier patrón de Columna + Número.
        const cellRegex = /([A-Z]\d+)/g; 

        // Función de reemplazo que se ejecuta por cada match encontrado (ej: A1, B2)
        expression = expression.replace(cellRegex, (match) => {
            const key = match;
            let value = estado[key] || '0';

            // Si el valor almacenado es un resultado calculado de fórmula, debe ser usado como número.
            // Buscamos si hay el marcador __FORMULA_START__
            if (typeof value === 'string' && value.includes("__FORMULA_START__:")) {
                const formulaMatch = value.match(/^__FORMULA_START__:.*\|(.+)$/);
                if (formulaMatch) {
                    value = formulaMatch[1]; // Usar el resultado calculado
                }
            }

            // Intentamos convertir a número, si falla, usamos 0 o mantenemos la cadena para evitar errores.
            const numValue = parseFloat(value);
            return isNaN(numValue) ? '0' : value; 
        });

        // Evaluación segura usando eval() (solo porque es un entorno controlado de app).
        // Nota: Ya no necesitamos reemplazar operadores explícitamente, ya que el regex captura las referencias.
        const result = Function(`return ${expression}`)();
        if (!isNaN(result)) {
             return result.toString();
        }
    } catch (e) {
        console.error("Error al evaluar la fórmula:", e);
    }

    // Si todo falla, devolvemos null para que el input raw se mantenga o se muestre como texto.
    return null;
}
