function render() {
    const cells = document.querySelectorAll('#spreadsheet td');
    cells.forEach(cell => {
        const col = cell.dataset.col;
        const row = cell.dataset.row;
        const key = `${col}${row}`;

        // Actualiza el contenido visible de la celda con lo que está en estado
        if (estado[key] !== undefined) {
            let displayValue = estado[key];

            // Verificar si el valor almacenado es una fórmula calculada. Si lo es, mostramos solo el resultado.
            const formulaMatch = displayValue ? displayValue.match(/^__FORMULA_START__:(.+?)\|(.+)$/) : null;

            if (formulaMatch) {
                displayValue = formulaMatch[2]; // Mostrar la parte del resultado
            } else {
                 displayValue = String(estado[key]); 
            }

            cell.textContent = displayValue;
        } else {
             cell.textContent = ''; // Asegura que si por alguna razón falta, esté vacío
        }
    });
}
