function generateKeys() {
    const columns = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    const rows = 20;
    let keys = {};
    for (let r = 1; r <= rows; r++) {
        for (let c = 0; c < columns.length; c++) {
            const colChar = columns[c];
            // Inicializar el estado con un objeto que contiene valor y color por defecto
            keys[`${colChar}${r}`] = { value: '', color: '#FFFFFF' }; 
        }
    }
    return keys;
}
