function selectColumn(col) {
    // 1. Deseleccionar cualquier columna previamente seleccionada (limpiar controles y estado visual)
    const currentCol = window.selectedColumn;
    if (currentCol) {
        document.querySelectorAll('.column-header button').forEach(btn => btn.disabled = true);
        document.getElementById(`control-${currentCol}`)?.classList.add('hidden');
    }

    // 2. Actualizar el estado de la columna seleccionada
    window.selectedColumn = col;

    // 3. Activar los controles para la nueva columna (solo si existe)
    if (!col) {
        console.log("Ninguna columna seleccionada.");
        return;
    }

    const controlsContainer = document.getElementById(`control-${col}`);
    if (controlsContainer) {
        // Habilitar botones y mostrar el panel de control
        document.querySelectorAll('.column-header button').forEach(btn => btn.disabled = true); // Deshabilitar todos primero
        controlsContainer.classList.remove('hidden');

        const deleteBtn = controlsContainer.querySelector('[data-action="delete"]');
        const clearBtn = controlsContainer.querySelector('[data-action="clear"]');
        const colorBtn = controlsContainer.querySelector('[data-action="color"]');

        if (deleteBtn) deleteBtn.disabled = false;
        if (clearBtn) clearBtn.disabled = false;
        if (colorBtn) colorBtn.disabled = false;
    }

    // 4. Redibujar para reflejar el cambio en la UI si es necesario (ej: resaltar header)
    render();
}
