### FUNCION: handleColumnAction
```js
function handleColumnAction(action, col) {
    if (!col) return;

    const keysToAffect = [];
    for (let r = 1; r <= 20; r++) {
        keysToAffect.push(`${col}${r}`);
    }

    switch (action) {
        case 'clear':
            // Borra el contenido de todas las celdas en la columna seleccionada
            for (const key of keysToAffect) {
                updateCell(col, 1, ''); // El segundo argumento es solo placeholder para actualizar estado. La clave se usa directamente.
                estado[key] = '';
            }
            console.log(`Columna ${col} vaciada.`);
            break;

        case 'delete':
            // Simula la eliminación borrando todos los datos asociados a esa columna del estado
            for (const key of keysToAffect) {
                delete estado[key];
            }
            console.log(`Columna ${col} eliminada de estados.`);
            break;

        case 'color':
            // Aplica un color visual a todas las celdas de la columna seleccionada
            const cells = document.querySelectorAll(`.column-header[data-col="${col}"] + td`);
            if (cells.length > 0) {
                const color = prompt("Por favor, introduce el código HEX o nombre del color que deseas aplicar (ej: #ffcccc):");
                if (color && color.trim() !== '') {
                    cells.forEach(cell => {
                        cell.style.backgroundColor = color;
                    });
                    console.log(`Columna ${col} coloreada de ${color}.`);
                }
            }
            break;
    }

    // Persistenciar cambios y actualizar la vista
    guardar();
    render(); // Re-renderiza para asegurar que los elementos visuales se actualicen correctamente (ej: si el color requiere un re-draw)
}
