            let sum = 0;
            for (const key of keys) {
                const value = estado[key] || '0';
                // Intentamos convertir a número para sumar. Si falla, se trata como cero.
                const numValue = parseFloat(value);
                if (!isNaN(numValue)) {
                    sum += numValue;
                }
            }
