function updateCell(col, row, value) {
    const key = `${col}${row}`;
    if (estado[key] !== undefined) {
        estado[key] = String(value);
        console.log(`Estado actualizado para ${key}: "${value}"`);
    } else {
        console.warn(`Clave inválida: ${key}`);
    }
