 */
function deleteColumn(col) {
    if (!/^[A-J]$/.test(col)) return;

    // 1. Eliminar el estado de la columna
    const keysToDelete = getColKeys(col);
    keysToDelete.forEach(key => {
        delete estado[key];
    });

    // 2. Modificar el DOM: eliminar encabezado
    const headerEl = document.querySelector(`.col-header[data-col="${col}"]`);
    if (headerEl) {
