function renderControls() {
    const col = estado.selectedColumn;
    const controlsDiv = document.getElementById('column-controls');
    if (!controlsDiv) return;

    // Limpiar controles anteriores
    controlsDiv.innerHTML = '';

    if (!col) {
        controlsDiv.style.display = 'none';
        return;
    }

    controlsDiv.style.display = 'flex';

    // 1. Control de Borrar Columna (Clear Column)
    const clearButton = document.createElement('button');
    clearButton.textContent = `🗑️ Borrar columna ${col}`;
    clearButton.className = 'control-btn';
    clearButton.onclick = () => {
        if(confirm(`¿Está seguro de borrar todo el contenido de la columna ${col}?`)) {
            clearColumn(col);
        }
    };

    // 2. Control de Color (Color Picker)
    const colorGroup = document.createElement('div');
    colorGroup.className = 'control-group';
    colorGroup.innerHTML = `
        <label for="column-color">Color:</label>
        <input type="color" id="column-color" value="#ff0000">
        <button class="control-btn color-btn">Aplicar Color</button>
    `;

    const colorInput = document.getElementById('column-color');
    const applyColorBtn = colorGroup.querySelector('.control-btn:last-child');

    // Asignar el evento de color
    applyColorBtn.onclick = () => {
        const color = colorInput.value;
        colorColumn(col, color);
    };


    // 3. Añadir controles al contenedor
    controlsDiv.appendChild(clearButton);
    controlsDiv.appendChild(colorGroup);
}
