### FUNCION: selectRow
```js
function selectRow(event) {
    const target = event.target;
    if (!target || !target.classList.contains('row-header')) return;

    let rowNumberStr = target.textContent.trim();
    const rowNumber = parseInt(rowNumberStr);

    // 1. Deseleccionar la fila actual (si existe)
    document.querySelectorAll('.row-header').forEach(header => {
        header.style.backgroundColor = '';
        header.style.cursor = 'pointer';
    });

    // 2. Seleccionar y actualizar estado
    target.style.backgroundColor = '#e0f7fa'; // Light cyan background for selection
    target.style.cursor = 'default';

    estado.selectedRow = rowNumber;
    guardar();
    renderControlsVisibility();
}
```

### FUNCION: deleteSelectedRow
```js
function deleteSelectedRow() {
    const selectedRowNum = estado.selectedRow;
    if (!selectedRowNum) return alert("Por favor, seleccione una fila primero.");

    if (!confirm(`¿Está seguro de que desea borrar la Fila ${selectedRowNum}? Esta acción es irreversible.`)) {
        return;
    }

    const rowCells = document.querySelectorAll(`#spreadsheet tbody tr:nth-child(${selectedRowNum}) td`);
    let keysToDelete = [];

    // 1. Recolectar todas las claves de la fila seleccionada
    rowCells.forEach(cell => {
        keysToDelete.push(`${cell.dataset.col}${cell.dataset.row}`);
    });

    // 2. Limpiar el estado (borrar los datos)
    keysToDelete.forEach(key => delete estado[key]);

    // 3. Eliminar la fila del DOM
    const rowToRemove = document.querySelector(`#spreadsheet tbody tr:nth-child(${selectedRowNum})`);
    if (rowToRemove) {
        rowToRemove.remove();
    }

    // 4. Actualizar estado y vista
    estado.selectedRow = null;
    guardar();
    render();
    clearControls();
}
```

