function deleteRowFromDOM(rowNum) {
    const row = document.querySelector(`tbody tr[data-row="${rowNum}"]`);
    if (row) {
        // 1. Remover elementos del DOM
        row.remove();

        // 2. Limpiar el estado de las celdas de esa fila
        for (let colCode = 0; colCode < 10; colCode++) { // A-J
            const colChar = String.fromCharCode('A'.charCodeAt(0) + colCode);
            const key = `${colChar}${rowNum}`;
            if (estado[key] !== undefined) {
                delete estado[key];
            }
        }

        // 3. Actualizar la selección y guardar/render
        window.selectedRowId = null;
        guardar();
        render();
    } else {
        console.warn(`No se encontró la fila ${rowNum} para eliminar.`);
    }
}
