### FUNCION: selectRow
```javascript
/**
 * Establece la fila seleccionada y actualiza los controles.
 * @param {number} rowNumber El número de fila seleccionado (1-20).
 */
function selectRow(rowNumber) {
    // 1. Deseleccionar cualquier fila previa visualmente
    document.querySelectorAll('.row-header').forEach(th => th.classList.remove('selected'));

    if (isNaN(rowNumber) || rowNumber < 1 || rowNumber > 20) {
        console.warn("Número de fila inválido:", rowNumber);
        return;
    }

    // 2. Seleccionar la nueva fila visualmente
    const selectedHeader = document.querySelector(`.row-header[data-row="${rowNumber}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    // 3. Actualizar estado de selección y controles
    window.selectedRow = rowNumber;
    updateControls(rowNumber);
}
```

### FUNCION: clearSelectedRow
```javascript
/**
 * Borra el contenido de todas las celdas de la fila seleccionada, actualizando el estado.
 */
function clearSelectedRow() {
    const row = window.selectedRow;
    if (!row) {
        alert("Por favor, seleccione una fila primero.");
        return;
    }

    let changesMade = false;
    // Iteramos sobre todas las columnas (A-J) para la fila seleccionada
    for (let i = 0; i < 10; i++) {
        const colChar = String.fromCharCode('A'.charCodeAt(0) + i);
        const key = `${colChar}${row}`;

        // Si el estado actual no está vacío, lo borramos y marcamos cambio
        if (estado[key] !== '' && estado[key] !== null) {
            estado[key] = '';
            changesMade = true;
        }
    }

    if (changesMade) {
        console.log(`Fila ${row} vaciada exitosamente.`);
        guardar();
        render();
    } else {
        alert("La fila ya está completamente vacía.");
    }
}
