### FUNCION: setBackgroundColorForSelectedRow
```javascript
/**
 * Cambia el color de fondo de todas las celdas en la fila seleccionada.
 * @param {string} color El color hexadecimal o nombre del color CSS (ej: '#ffff00' o 'yellow').
 */
function setBackgroundColorForSelectedRow(color) {
    const row = window.selectedRow;
    if (!row) {
        alert("Por favor, seleccione una fila primero.");
        return;
    }

    // 1. Limpiar cualquier color anterior de la fila seleccionada (para evitar acumulación)
    document.querySelectorAll(`.row-header[data-row="${row}"]`).forEach(th => th.classList.remove('selected'));
    document.querySelectorAll(`#spreadsheet tr:nth-child(${row + 1}) td`).forEach(td => {
        td.style.backgroundColor = ''; // Resetear el color de fondo
    });

    // 2. Aplicar el nuevo color a todas las celdas de la fila (A-J)
    const rowCells = document.querySelectorAll(`#spreadsheet tr:nth-child(${row + 1}) td`);
    rowCells.forEach(td => {
        td.style.backgroundColor = color;
    });

    console.log(`Fondo de la fila ${row} cambiado a ${color}.`);
    // Nota: El cambio de color es puramente visual y no afecta el estado (estado), solo se renderiza en el DOM.
}
